      hireStartDateRequired: 'Start date is required.',
      rejectModalTitle: 'Rejection reason',
      rejectModalIntro: 'Select the main reason. It will appear on the candidate timeline.',
      hireModalTitle: 'Start date',
      hireModalIntro: 'Enter the agreed start date when marking as hired.',
      hireDateHint: 'Use the calendar to pick the day.',
      offerTitle: 'Offer / acceptance',
      offerHint:
        'Minimal offer log (salary and date). Not an offer letter or e-sign suite.',
      offerFormTitle: 'Log offer',
      offerFormHint: 'Use Accepted / Declined when the candidate responds.',
      offerSave: 'Save offer',
      offerSaved: 'Offer updated.',
      offerAdd: 'Log offer',
      offerAddShort: '+ Offer',
      offerEdit: 'Edit offer',
      offerStatusLabel: 'Status',
      offerSalaryLabel: 'Salary / package',
      offerSalaryPh: 'e.g. R$ 12,000 CLT',
      offerStartDateLabel: 'Proposed start',
      offerNotesLabel: 'Notes (optional)',
      offerNotesPh: 'Terms, benefits, pending items…',
      offerSalaryLine: 'Package: {n}',
      offerStartLine: 'Start: {d}',
      offerStatus: {
        none: 'No offer',
        proposed: 'Offer sent',
        accepted: 'Accepted',
        declined: 'Declined',
      },
      modalCancel: 'Cancel',
      modalConfirm: 'Confirm',
